const text=(x,y,s,size=17,fill='#293b44',anchor='start')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" text-anchor="${anchor}" font-family="Arial,Microsoft YaHei,sans-serif">${esc(s)}</text>`;
