function tube(x,y,color='#dcecf3',level=.5){return `<path d="M${x} ${y}V${y+160}A27 27 0 0 0 ${x+54} ${y+160}V${y}" fill="#f9ffff" fill-opacity=".5" stroke="#536f7c" stroke-width="3"/><path d="M${x+4} ${y+180-150*level}H${x+50}V${y+158}A23 23 0 0 1 ${x+4} ${y+158}Z" fill="${color}"/><path d="M${x-5} ${y}H${x+59}" stroke="#536f7c" stroke-width="4"/>`;}
function bubbles(x,y,u,count=8){return Array.from({length:count},(_,i)=>{const yy=y-((u*160+i*27)%150),xx=x+Math.sin(i*3.1)*22;return `<circle cx="${f(xx)}" cy="${f(yy)}" r="${3+i%3}" fill="#f7ffff" fill-opacity=".85" stroke="#7bafba"/>`;}).join('');}
function flame(x,y,on,color='#e7a83f'){return on?`<path d="M${x} ${y}C${x-25} ${y-35} ${x-9} ${y-53} ${x} ${y-75}C${x+6} ${y-43} ${x+34} ${y-24} ${x} ${y}Z" fill="${color}" stroke="#ae7132"/><path d="M${x} ${y-4}Q${x-12} ${y-20} ${x} ${y-39}Q${x+15} ${y-16} ${x} ${y-4}" fill="#f8e69a"/>`:'';}
function notes(r){return `<rect x="610" y="95" width="258" height="265" fill="#f2f0de" stroke="#b7b39b"/>${text(628,122,'观察与分析',18)}${lines(628,151,r.conclusion,13,15)}${(r.readings||[]).slice(0,3).map((v,i)=>{const full=`${v.label}: ${v.value} ${v.unit}`;return `<g><title>${esc(full)}</title>${lines(628,274+i*28,[...full].slice(0,40).join(''),20,11)}</g>`;}).join('')}`;}
